def ComplexFinitelySeparated (ev : D → I → ℂ) (S : Set I) (M N : Set D) : Prop :=
  ∃ ε : ℝ, 0 < ε ∧ ∃ F : Finset I, (↑F : Set I) ⊆ S ∧
    ∀ m ∈ M, ∀ n ∈ N, ∃ i ∈ F, ε ≤ ‖ev m i - ev n i‖

